478	    //pseudo selectors :first-child, :last-child, :nth-child, ...
479	    private static final Pattern NthStepOffset = Pattern.compile("(([+-])?(\\d+)?)n(\\s*([+-])?\\s*\\d+)?", Pattern.CASE_INSENSITIVE);
480	    private static final Pattern NthOffset = Pattern.compile("([+-])?(\\d+)");
481	
482	    private Evaluator cssNthChild(boolean last, boolean ofType) {
483	        String raw = consumeParens(); // arg is like "odd", or "-n+2", within nth-child(odd), optionally followed by " of S"
484	        final int ofIdx = indexOfOfClause(raw);
485	        final String arg = normalize(ofIdx >= 0 ? raw.substring(0, ofIdx) : raw);
486	        final boolean hasOf = ofIdx >= 0;
487	
488	        if (hasOf && ofType)
489	            throw new Selector.SelectorParseException(
490	                "Could not parse query '%s': 'of S' is only supported by :nth-child and :nth-last-child", query);
491	
492	        final int step, offset;
493	        if ("odd".equals(arg)) {
494	            step = 2;
495	            offset = 1;
496	        } else if ("even".equals(arg)) {
497	            step = 2;
498	            offset = 0;
499	        } else {
500	            Matcher stepOffsetM, stepM;
501	            if ((stepOffsetM = NthStepOffset.matcher(arg)).matches()) {
502	                if (stepOffsetM.group(3) != null) // has digits, like 3n+2 or -3n+2
503	                    step = Integer.parseInt(stepOffsetM.group(1).replaceFirst("^\\+", ""));
504	                else // no digits, might be like n+2, or -n+2. if group(2) == "-", it’s -1;
505	                    step = "-".equals(stepOffsetM.group(2)) ? -1 : 1;
506	                offset =
507	                    stepOffsetM.group(4) != null ? Integer.parseInt(stepOffsetM.group(4).replaceFirst("^\\+", "")) : 0;
508	            } else if ((stepM = NthOffset.matcher(arg)).matches()) {
509	                step = 0;
510	                offset = Integer.parseInt(stepM.group().replaceFirst("^\\+", ""));
511	            } else {
512	                throw new Selector.SelectorParseException("Could not parse nth-index '%s': unexpected format", arg);
513	            }
514	        }
515	
516	        if (hasOf) {
517	            String subQuery = raw.substring(ofIdx + 2).trim(); // skip the "of" keyword
518	            Validate.notEmpty(subQuery, ":nth-child(An+B of S) selector S must not be empty");
519	            Evaluator selector = parse(subQuery); // a comma-separated complex selector list; validates the full grammar
520	            return new Evaluator.IsNthChildOf(step, offset, last, selector);
521	        }
522	
523	        return ofType
524	            ? (last ? new Evaluator.IsNthLastOfType(step, offset) : new Evaluator.IsNthOfType(step, offset))
525	            : (last ? new Evaluator.IsNthLastChild(step, offset) : new Evaluator.IsNthChild(step, offset));
526	    }
527	
528	    /**
529	     Finds the index of the {@code of} keyword separating An+B from the selector list in an
530	     {@code :nth-child(An+B of S)} argument. The keyword must be bounded on both sides by whitespace, and is not
531	     matched inside quoted strings (so attribute values containing " of " are preserved).
532	     @return the index of the 'o' in 'of', or -1 if there is no of clause
533	     */
534	    private static int indexOfOfClause(String arg) {
535	        boolean inSingle = false;
536	        boolean inDouble = false;
537	        boolean prevEscaped = false;
538	        for (int i = 0; i < arg.length(); i++) {
539	            char c = arg.charAt(i);
540	            if (c == '\\' && i + 1 < arg.length()) {
541	                i++; // skip the escaped char
542	                prevEscaped = true;
543	                continue;
544	            }
545	            if (!inDouble && c == '\'')
546	                inSingle = !inSingle;
547	            else if (!inSingle && c == '"')
548	                inDouble = !inDouble;
549	
550	            if (!inSingle && !inDouble && !prevEscaped
551	                && i > 0 && StringUtil.isWhitespace(arg.charAt(i - 1))
552	                && arg.regionMatches(true, i, "of", 0, 2)
553	                && i + 2 < arg.length() && StringUtil.isWhitespace(arg.charAt(i + 2))) {
554	                return i;
555	            }
556	            prevEscaped = false;
557	        }
558	        return -1;
559	    }
560	
561	    private String consumeParens() {
562	        return tq.chompBalanced('(', ')');
563	    }
564	
565	    private int consumeIndex() {
566	        String index = consumeParens().trim();
567	        Validate.isTrue(StringUtil.isNumeric(index), "Index must be numeric");
568	        return Integer.parseInt(index);
569	    }
570	
571	    // pseudo selector :has(el)
572	    private Evaluator has() {
573	        return parseNested(StructuralEvaluator.Has::new, ":has() must have a selector");
574	    }
575	
576	    // pseudo selector :is()
577	    private Evaluator is() {
578	        return parseNested(StructuralEvaluator.Is::new, ":is() must have a selector");
579	    }
580	
581	    private Evaluator parseNested(Function<Evaluator, Evaluator> func, String err) {
582	        Validate.isTrue(tq.matchChomp('('), err);
583	        Evaluator eval = parseSelectorGroup();
584	        Validate.isTrue(tq.matchChomp(')'), err);
585	        return func.apply(eval);
586	    }
587	
588	    // pseudo selector :contains(text), containsOwn(text)
589	    private Evaluator contains(boolean own) {
590	        String query = own ? ":containsOwn" : ":contains";
591	        String searchText = TokenQueue.unescape(consumeParens());
592	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
593	
594	        if (inNodeContext)
595	            return new NodeEvaluator.ContainsValue(searchText);
596	
597	        return own
598	            ? new Evaluator.ContainsOwnText(searchText)
599	            : new Evaluator.ContainsText(searchText);
600	    }
601	
602	    private Evaluator containsWholeText(boolean own) {
603	        String query = own ? ":containsWholeOwnText" : ":containsWholeText";
604	        String searchText = TokenQueue.unescape(consumeParens());
605	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
606	        return own
