import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;

public class Check {
    static String ids(Elements els) {
        StringBuilder sb = new StringBuilder();
        for (var el : els) sb.append(el.id()).append(',');
        return sb.toString();
    }
    public static void main(String[] args) {
        Document doc = Jsoup.parse(
            "<a id=a data-v=\" A B \"></a><a id=b data-v=\"a=b\"></a><a id=c data-v=\"AlphaBeta\"></a>" +
            "<a id=d data-v=\"\"></a><i id=e></i>");
        System.out.println("quoted space: " + ids(doc.select("[data-v=\" A B \"]")));      // expect a
        System.out.println("quoted equals: " + ids(doc.select("[data-v=\"a=b\"]")));       // expect b
        System.out.println("neq quoted:    " + ids(doc.select("[data-v!=\"a=b\"]")));      // expect a,c,d,e
        System.out.println("prefix i:      " + ids(doc.select("[data-v^=alpha i]")));      // expect c
        System.out.println("prefix s:      " + ids(doc.select("[data-v^=alpha s]")));      // expect none
        System.out.println("prefix bare:   " + ids(doc.select("[data-v^=alpha]")));        // expect c (bare = insensitive)
        System.out.println("escaped key:   " + ids(doc.select("[data-\\76 =\"a=b\"]")));   // expect b
        System.out.println("exists:        " + ids(doc.select("[data-v]")));               // a,b,c,d
        System.out.println("ws around op:  " + ids(doc.select("[ data-v = \"a=b\" ]")));   // b
        // error cases must throw SelectorParseException and doc stays usable
        String[] bad = {"[data-v", "[data-v='a", "[data-v=", "[data-v=a b]", "[data-v='a' i s]",
            "[data-v='a' x]", "[data-v i]", "[data-v='a' i x]", "[data-v=1] [", "[data-v=\"a\"]"};
        for (String q : bad) {
            try {
                Elements r = doc.select(q);
                System.out.println("NO THROW for " + q + " -> " + r.size());
            } catch (org.jsoup.select.Selector.SelectorParseException ex) {
                System.out.println("ok throw: " + q);
            }
        }
        System.out.println("after errors, exists still: " + ids(doc.select("[data-v]")));
    }
}
EOF
